#include "actual_task_metrics.hpp"
#include <iostream>
#include <limits>
int main(){using namespace phase5_actual_task_metrics_v1;const Pose zero{{0,0,0},{1,0,0,0,1,0,0,0,1}};auto near=[](double a,double b){return std::abs(a-b)<=1e-12;};auto rot=[&](double angle){auto p=zero;p.rotation={std::cos(angle),-std::sin(angle),0,std::sin(angle),std::cos(angle),0,0,0,1};return p;};auto e=measure(zero,zero);if(e.translation_m!=0||e.orientation_rad!=0||!e.within_10mm_005rad)return 1;auto translated=zero;translated.position={.003,.004,0};e=measure(zero,translated);if(!near(e.translation_m,.005))return 2;const double pi=std::acos(-1.);for(double a:{1e-12,.05,pi*.5,pi-1e-12,pi}){e=measure(zero,rot(a));if(!near(e.orientation_rad,a))return 3;}translated.position={.011,0,0};if(measure(zero,translated).within_10mm_005rad||measure(zero,rot(.051)).within_10mm_005rad)return 4;auto bad=zero;bad.rotation[0]=-1;bool refused=false;try{measure(bad,zero);}catch(const std::invalid_argument&){refused=true;}if(!refused)return 5;bad=zero;bad.position[1]=std::numeric_limits<double>::quiet_NaN();refused=false;try{measure(zero,bad);}catch(const std::invalid_argument&){refused=true;}if(!refused)return 6;std::cout<<"PASS actual world position/SO3 angle metric zero/translation/nearzero/pi/limits/invalidrotation/nonfinite; pure pose arithmetic, no runtime task evidence\n";}
